import re

def add_groups(text, cur, rows):
    for g in re.findall(r'\*([^*]+)', text):
        g = g.strip()
        if g and g != 'None':
            rows.append({'Membership': cur, 'Group': g})

def parse(lines):
    kv = {}
    kvl = []
    rows = []
    rl = []
    skip = []
    cur = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if re.match(r'^[A-Za-z]:\\.*>', s) or s.startswith('The command completed'):
            skip.append(i)
            cur = None
            continue
        if l[:1].isspace() and cur and s.startswith('*'):
            add_groups(s, cur, rows)
            rl.append(i)
            continue
        m = re.match(r'^(\S(?:.*?\S)?)(?:\s{2,}(.*?))?\s*$', l)
        if not m:
            continue
        k = m.group(1)
        v = m.group(2) or ''
        if 'membership' in k.lower():
            cur = k
            rl.append(i)
            add_groups(v, cur, rows)
        else:
            cur = None
            kv[k] = v
            kvl.append(i)
    blocks = []
    if kvl:
        blocks.append({'name': 'account', 'kind': 'kv', 'lines': kvl, 'records': [kv]})
    if rl:
        blocks.append({'name': 'group memberships', 'kind': 'table', 'lines': rl, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
